  if lower:sub(1, 8) == "https://" or lower:sub(1, 7) == "http://" or raw:sub(1, 2) == "//" then
    local rest = raw
    if lower:sub(1, 8) == "https://" then rest = raw:sub(9)
    elseif lower:sub(1, 7) == "http://" then rest = raw:sub(8)
    else rest = raw:sub(3) end
    local slash = rest:find("/", 1, true)
    local hostport = slash and rest:sub(1, slash - 1) or rest
    path = slash and rest:sub(slash) or "/"
    if hostport:find("@", 1, true) or hostport:find(":", 1, true) or hostport:lower() ~= HOST then
      error("host not allowed")
    end
  elseif raw:sub(1, 1) == "/" then
    path = raw
  else
    path = "/" .. raw
  end
  path = path:lower()
  while path:find("//", 1, true) do path = path:gsub("//", "/", 1) end
  if #path > 1 then path = path:gsub("/+$", "") end
  if path == "" then path = "/" end
  if not PATHS[path] then error("unknown path") end
  if path == "/" then return M.ORIGIN .. "/" end
  return M.ORIGIN .. path
end

function M.home_url() return canonical_url("/") end
function M.page_url(key)
  local path = PAGES[key]
  if not path then error("unknown page") end
  return canonical_url(path)
end
function M.blog_url(slug)
  local path = BLOGS[slug]
  if not path then error("unknown blog") end
  return canonical_url(path)
end
function M.locale_url(locale, key)
  if locale ~= "en" and locale ~= "zh" then error("locale not available") end
  local path = PAGES[key]
  if not path then error("unknown page") end
  if locale == "zh" and ENGLISH_ONLY[path] then error("locale not available") end
  if locale == "en" then return canonical_url(path) end
  return canonical_url(path == "/" and "/zh" or ("/zh" .. path))
end
function M.canonical_url(input) return canonical_url(input) end
return M
